def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(v)

    # self harm flag
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 < 0 or q9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = bool(q9 > 0)

    n_missing = sum(pd.isna(vals))
    if n_missing >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        # scale up: sum * 9 / 8, round half up
        from decimal import Decimal, ROUND_HALF_UP
        scaled = (Decimal(str(ans_sum)) * Decimal('9') / Decimal('8'))
        total = int(scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = int(np.sum(vals))
        prorated = False

    # band
    if total <= 4:
        band = "none-minimal"
    elif total <= 9:
        band = "mild"
    elif total <= 14:
        band = "moderate"
    elif total <= 19:
        band = "moderately severe"
    else:
        band = "severe"

    return total, band, prorated, sh_flag

