import numpy as np

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

# Let's test all possible subsets of items as reverse-scored, or different formulas.
# Or let's search over possible reverse coding definitions.
# Guide says: "negatively worded statements are questions 3, 5, 8, 9 and 10... score is 3 minus the stored answer".
# What did the pipeline do? Let's check alternative rules.

def test_pipeline_rses(rev_list, formula_type):
    totals = []
    for idx, row in raw.iterrows():
        scored = []
        for i in range(1, 11):
            v = row[f'rses_{i}']
            if pd.isna(v) or v not in [0, 1, 2, 3]:
                scored.append(np.nan)
            else:
                if i in rev_list:
                    if formula_type == '3-v':
                        scored.append(3 - v)
                    elif formula_type == '4-v':
                        scored.append(4 - v)
                    elif formula_type == 'not_reversed':
                        scored.append(v)
                else:
                    if formula_type == 'reversed_pos': # maybe positive were reversed?
                        scored.append(3 - v)
                    else:
                        scored.append(v)
        n_miss = sum(pd.isna(scored))
        if n_miss >= 2:
            totals.append(np.nan)
        elif n_miss == 1:
            s = np.nansum(scored)
            from decimal import Decimal, ROUND_HALF_UP
            tot = int(Decimal(str(s) * 10 / 9).quantize(Decimal('1'), rounding=ROUND_HALF_UP)) # wait, proportion
            # actually scale up formula: s * 10 / (10 - n_miss) -> s * 10 / 9
            tot = int(Decimal(str(s * 10 / 9)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            totals.append(tot)
        else:
            totals.append(int(np.nansum(scored)))
    return np.array(totals)

# Try all subsets of size 5? Or common mistakes:
# Mistake 1: positive items reversed (1, 2, 4, 6, 7) instead of (3, 5, 8, 9, 10).
# Mistake 2: reverse coding using 4 minus v (1-4 scale where max is 4).
# Mistake 3: no items reversed.
# Mistake 4: wrong item numbers reversed (e.g., 3, 6, 8, 9, 10 or similar).

candidates = [
    ([1, 2, 4, 6, 7], '3-v'),
    ([3, 5, 8, 9, 10], '4-v'),
    ([3, 5, 8, 9, 10], 'not_reversed'),
    ([1, 3, 5, 8, 9, 10], '3-v'),
    ([2, 5, 8, 9, 10], '3-v'),
    ([3, 4, 8, 9, 10], '3-v'),
]

for rev_l, form in candidates:
    t = test_pipeline_rses(rev_l, form)
    matches = np.sum(t == out['rses_total'].values | (pd.isna(t) & pd.isna(out['rses_total'])))
    print(f"rev={rev_l}, form={form} -> matches: {matches} / 505")
"}

