# Let's test all possible subsets of 5 items out of 10 for reverse coding (256 combinations) with formula 3-v.
import itertools
import pandas as pd
import numpy as np
from decimal import Decimal, ROUND_HALF_UP

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

best_match = 0
best_rev = None

for r in itertools.combinations(range(1, 11), 5):
    totals = []
    for idx, row in raw.iterrows():
        scored = []
        for i in range(1, 11):
            v = row[f'rses_{i}']
            if pd.isna(v) or v not in [0, 1, 2, 3]:
                scored.append(np.nan)
            else:
                if i in r:
                    scored.append(3 - v)
                else:
                    scored.append(v)
        n_miss = sum(pd.isna(scored))
        if n_miss >= 2:
            totals.append(np.nan)
        elif n_miss == 1:
            s = np.nansum(scored)
            tot = int(Decimal(str(s * 10 / 9)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            totals.append(tot)
        else:
            totals.append(int(np.nansum(scored)))
    t_arr = np.array(totals)
    matches = np.sum((t_arr == out['rses_total'].values) | (pd.isna(t_arr) & pd.isna(out['rses_total'])))
    if matches > best_match:
        best_match = matches
        best_rev = r

print(f"Best rev set: {best_rev} with {best_match} matches out of 505")
